compile.workshop:
variables {
    global:
        0: g
    player:
        0: p
}

rule ("action rewrites") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Create HUD Text(Event Player, Null, Global.g, Null, Left, 3, Color(Yellow), Color(Yellow), Color(Yellow), Visible To and String, Default Visibility);
        Set Ultimate Charge(Event Player, Absolute Value(0.5));
        Set Ultimate Charge(Event Player, 50);
        Set Ultimate Charge(Event Player, Absolute Value(-2.5));
        Wait Until(First Of(Null), 3);
        Set Ability 1 Enabled(Event Player, First Of(Null));
        Add Health Pool To Player(Event Player, Armor, 3, True, First Of(Null));
        Start Forcing Player Outlines(Event Player, Event Player, False, Null, Always);
        Start Forcing Player Outlines(Event Player, Event Player, True, Color(Red), Always);
    }
}

